import { readFileSync } from 'node:fs'
import path from 'node:path'
import { describe, expect, it } from 'vitest'
import { createStatusIngestStore, validateStatusPush, STATUS_PUSH_SCHEMA } from '../../server/domain/statusIngest.js'
import { normalizeRuntimeStatus } from '../../server/domain/normalize.js'

// TEST_ONLY: generated by the Python status_projection_publisher from a synthetic Core document, not Production evidence.
const fixture = JSON.parse(readFileSync(path.resolve(process.cwd(), 'tests', 'fixtures', 'core-status-push.json'), 'utf8'))
const NOW = new Date('2023-11-14T22:15:00.000Z')
const clone = () => structuredClone(fixture)

describe('Core -> Web status push contract (pure, non-networked)', () => {
  it('accepts the Python-built envelope and keeps the Core timestamp', () => {
    const result = validateStatusPush(clone(), { now: NOW })
    expect(result.ok).toBe(true)
    expect(result.record.projection.generatedAt).toBe('2023-11-14T22:14:55.000Z')
    expect(result.record.sentAtMs).toBe(1_700_000_100_000)
    expect(result.record.receivedAt).toBe(NOW.toISOString())
  })

  it('the accepted projection normalizes through the existing adapter exactly like a fetched feed', () => {
    const accepted = validateStatusPush(clone(), { now: NOW }).record.projection
    const runtime = normalizeRuntimeStatus(accepted, { now: NOW })
    expect(runtime.freshness).toBe('FRESH')
    expect(runtime.status).toBe('HEALTHY')
    const byId = Object.fromEntries(runtime.components.map((component) => [component.id, component.status]))
    expect(byId.relay ?? 'UNKNOWN').toBe('UNKNOWN')
    expect(byId.ack ?? 'UNKNOWN').toBe('UNKNOWN')
    expect(byId.heartbeat ?? 'UNKNOWN').toBe('UNKNOWN')
  })

  it.each([
    ['null body', () => null],
    ['array body', () => []],
    ['extra envelope key', () => ({ ...clone(), token: 'x' })],
    ['missing key', () => { const body = clone(); delete body.sentAtMs; return body }],
    ['non-integer sentAtMs', () => ({ ...clone(), sentAtMs: 1.5 })],
    ['string sentAtMs', () => ({ ...clone(), sentAtMs: '1700000100000' })],
    ['zero sentAtMs', () => ({ ...clone(), sentAtMs: 0 })],
    ['projection extra key', () => { const body = clone(); body.projection.detail = 'free text'; return body }],
    ['projection missing key', () => { const body = clone(); delete body.projection.modes; return body }],
    ['wrong evidence source', () => { const body = clone(); body.projection.evidenceSource = 'LAB_MQTT'; return body }],
    ['unknown status vocabulary', () => { const body = clone(); body.projection.status = 'GREAT'; return body }],
    ['unknown component state', () => { const body = clone(); body.projection.components.broker = 'MAYBE'; return body }],
    ['unknown component name', () => { const body = clone(); body.projection.components.relay = 'ONLINE'; return body }],
    ['missing mandatory component', () => { const body = clone(); delete body.projection.components.uplink; return body }],
    ['non-boolean mode', () => { const body = clone(); body.projection.modes.dryRun = 'false'; return body }],
    ['free-text issue', () => { const body = clone(); body.projection.issues = ['token=abc']; return body }],
    ['non-array issues', () => { const body = clone(); body.projection.issues = 'MQTT_DISCONNECTED'; return body }],
    ['malformed generatedAt', () => { const body = clone(); body.projection.generatedAt = 'yesterday'; return body }],
    ['null generatedAt', () => { const body = clone(); body.projection.generatedAt = null; return body }],
    ['oversized', () => { const body = clone(); body.projection.issues = new Array(9000).fill('MQTT_DISCONNECTED'); return body }],
  ])('refuses %s', (_name, build) => {
    const result = validateStatusPush(build(), { now: NOW })
    expect(result.ok).toBe(false)
    expect(result.code).toBe('STATUS_PUSH_INVALID')
    expect(result.record).toBeNull()
  })

  it('refuses an unsupported schema or version', () => {
    expect(validateStatusPush({ ...clone(), schema: 'other' }, { now: NOW }).code).toBe('STATUS_PUSH_UNSUPPORTED')
    expect(validateStatusPush({ ...clone(), version: 2 }, { now: NOW }).code).toBe('STATUS_PUSH_UNSUPPORTED')
    expect(STATUS_PUSH_SCHEMA).toBe('aegis.idea3.status-push')
  })

  it('refuses stale and future evidence and stale or future envelopes', () => {
    const later = new Date(NOW.getTime() + 10 * 60_000)
    expect(validateStatusPush(clone(), { now: later }).code).toBe('STATUS_PUSH_STALE')
    const earlier = new Date(NOW.getTime() - 10 * 60_000)
    expect(validateStatusPush(clone(), { now: earlier }).code).toBe('STATUS_PUSH_FUTURE')
    const futureEvidence = clone()
    futureEvidence.projection.generatedAt = '2023-11-14T22:30:00.000Z'
    expect(validateStatusPush(futureEvidence, { now: NOW }).code).toBe('STATUS_PUSH_FUTURE')
    const staleEvidence = clone()
    staleEvidence.projection.generatedAt = '2023-11-14T21:00:00.000Z'
    expect(validateStatusPush(staleEvidence, { now: NOW }).code).toBe('STATUS_PUSH_STALE')
  })

  it('refuses a replayed, reordered or older-evidence push without changing the stored record', () => {
    const store = createStatusIngestStore()
    expect(store.accept(clone(), NOW).ok).toBe(true)
    const stored = store.current()
    expect(store.accept(clone(), NOW).code).toBe('STATUS_PUSH_REPLAY')
    const older = clone()
    older.sentAtMs -= 1000
    expect(store.accept(older, NOW).code).toBe('STATUS_PUSH_REPLAY')
    const olderEvidence = clone()
    olderEvidence.sentAtMs += 1000
    olderEvidence.projection.generatedAt = '2023-11-14T22:14:00.000Z'
    expect(store.accept(olderEvidence, NOW).code).toBe('STATUS_PUSH_REPLAY')
    expect(store.current()).toEqual(stored)
  })

  it('accepts a strictly newer push and replaces the record', () => {
    const store = createStatusIngestStore()
    store.accept(clone(), NOW)
    const next = clone()
    next.sentAtMs += 5000
    next.projection.generatedAt = '2023-11-14T22:15:00.000Z'
    next.projection.components.broker = 'DISCONNECTED'
    next.projection.status = 'DEGRADED'
    next.projection.issues = ['MQTT_DISCONNECTED']
    expect(store.accept(next, new Date(NOW.getTime() + 5000)).ok).toBe(true)
    expect(store.current().components.broker).toBe('DISCONNECTED')
  })

  it('an empty store, a refused first push and a missing clock never produce evidence', () => {
    const store = createStatusIngestStore()
    expect(store.current()).toBeNull()
    expect(store.accept({ nope: true }, NOW).ok).toBe(false)
    expect(store.current()).toBeNull()
    expect(validateStatusPush(clone(), {}).ok).toBe(false)
    expect(validateStatusPush(clone(), { now: new Date('x') }).ok).toBe(false)
  })

  it('the store returns copies so callers cannot mutate accepted evidence', () => {
    const store = createStatusIngestStore()
    store.accept(clone(), NOW)
    store.current().status = 'FAILED'
    expect(store.current().status).toBe('HEALTHY')
  })

  it('a LOCKDOWN uplink pushed as HEALTHY still normalizes to DEGRADED', () => {
    const body = clone()
    body.projection.components.uplink = 'LOCKDOWN'
    const accepted = validateStatusPush(body, { now: NOW }).record.projection
    expect(normalizeRuntimeStatus(accepted, { now: NOW }).status).toBe('DEGRADED')
  })

  it('has no network, filesystem, process or timer surface', () => {
    const source = readFileSync(path.resolve(process.cwd(), 'server', 'domain', 'statusIngest.js'), 'utf8')
    for (const forbidden of ['node:fs', 'node:net', 'node:http', 'child_process', 'fetch(', 'setTimeout', 'Date.now', 'process.env', 'express']) {
      expect(source).not.toContain(forbidden)
    }
  })
})
